import logging

class AccelChipProxy:
    accel_num = 0
    config_changed = False

    class ConfigWrapperProxy:

        def __init__(self, config, chip_name):
            self.config = config
            self.chip_name = chip_name

        def get(self, option, default=None, note_valid=True):
            return self.config.get(f"{self.chip_name}_{option}", default, note_valid=note_valid)

        def getint(self, option, default=None, minval=None, maxval=None, note_valid=True):
            return self.config.getint(f"{self.chip_name}_{option}", default, minval=minval, maxval=maxval, note_valid=note_valid)

        def getlist(self, option, default=None, sep=',', count=None, note_valid=True):
            return self.config.getlist(f"{self.chip_name}_{option}", default, sep=sep, count=count, note_valid=note_valid)

        def __getattr__(self, name):
            return getattr(self.config, name)

    def __init__(self, config):
        self.name = config.get_name()
        self.config = config
        for option in config.fileconfig.options(self.config.get_name()):
            config.get(option)

        self.accel_use_chip = config.get("accel_use_chip", "adxl345")
        self.cs_pin = config.get(f"{self.accel_use_chip}_cs_pin")
        self.cs_pin_mcu_name = self.cs_pin.split(":")[0]
        self.printer = config.get_printer()
        self.gcode = self.printer.lookup_object("gcode")
        self.configfile = self.printer.lookup_object("configfile")
        self.printer.register_event_handler("klippy:mcu_identified", self._handle_identify)
        self.printer.register_event_handler("klippy:connect_complete", self._handle_complete)

    def _handle_identify(self, mcu):
        logging.info(f"_handle_identify: {mcu._name}")
        muc_name = mcu._name
        if muc_name != self.cs_pin_mcu_name:
            logging.info(f"mcu_name: {muc_name} != {self.cs_pin_mcu_name}")
            return
        mcu_msg = mcu._serial.get_msgparser()
        logging.info(f"mcu_messages_by_name: {mcu_msg.messages_by_name.keys()}")
        while self.accel_use_chip == "adxl345":
            if "config_adxl345" in mcu_msg.messages_by_name:
                logging.info("adxl345_data in mcu_messages")
                from . import adxl345
                adxl345_obj = adxl345.ADXL345(self.ConfigWrapperProxy(self.config, "adxl345"))
                self.printer.objects[self.name] = adxl345_obj
                self.accel_use_chip = "adxl345"
                break
            if self.accel_use_chip == "lis2dw":
                if "config_lis2dw" in mcu_msg.messages_by_name:
                    logging.info("lis2dw_data in mcu_messages")
                    from . import lis2dw
                    lis2dw_obj = lis2dw.LIS2DW(self.ConfigWrapperProxy(self.config, "lis2dw"))
                    self.printer.objects[self.name] = lis2dw_obj
                    self.accel_use_chip = "lis2dw"
                    break
                logging.info("Accel_chip mismatch in mcu_messages")
                self.accel_use_chip = "adxl345" if self.accel_use_chip == "lis2dw" else "lis2dw"
                self.configfile.set(self.name, "accel_use_chip", self.accel_use_chip)
                self.configfile.cmd_SAVE_CONFIG_NORESTART(gcmd=None)

    def _handle_complete(self):
        logging.info("_handle_complete")
        cls = self.__class__
        cls.accel_num += 1
        if self.accel_use_chip == "adxl345":
            from . import adxl345
            adxl345_obj = self.printer.objects.get(self.name)
            if adxl345_obj.read_reg(adxl345.REG_DEVID) != adxl345.ADXL345_DEV_ID:
                self.configfile.set(self.name, "accel_use_chip", "lis2dw")
                logging.info("Not adxl345, use lis2dw")
                cls.config_changed = True
        elif self.accel_use_chip == "lis2dw":
            from . import lis2dw
            lis2dw_obj = self.printer.objects.get(self.name)
            if lis2dw_obj.read_reg(lis2dw.REG_LIS2DW_WHO_AM_I_ADDR) != lis2dw.LIS2DW_DEV_ID:
                self.configfile.set(self.name, "accel_use_chip", "adxl345")
                logging.info("Not lis2dw, use adxl345")
                cls.config_changed = True
        if cls.accel_num == 2:
            if cls.config_changed:
                logging.info("Chip mismatch,save_config")
                self.configfile.cmd_SAVE_CONFIG(gcmd=None)


def load_config(config):
    return AccelChipProxy(config)


def load_config_prefix(config):
    return AccelChipProxy(config)

